"""Review computation, TASK-20260929-75e9e4: complete trial division (a proof)
for every odd prime factor of every declared curve cell's order, including the
ordinary cells and the composite cell; and the experiment directory tree at the
current HEAD (zero runs). Own code."""
import json, math, subprocess
def td(m):
    if m % 2 == 0:
        return m == 2
    r = math.isqrt(m); d = 3
    while d <= r:
        if m % d == 0:
            return False
        d += 2
    return True
cells = {"CELL-K13": (8012, [2003]), "CELL-K17C": (130972, [137, 239]), "CELL-K19": (523492, [130873]),
         "CELL-K23": (8383412, [2095853]), "CELL-K41": (2199025563772, [549756390943]),
         "CELL-O19": (523646, [261823]), "CELL-RC1": (130412, [32603])}
out = {}
for c, (N, ps) in cells.items():
    prod_ok = N == (4 if c != "CELL-O19" else 2) * math.prod(ps)
    out[c] = {"order": N, "odd_primes": ps, "product_matches": prod_ok, "each_prime_by_complete_trial_division": [td(p) for p in ps]}
