"""Review computation, TASK-20260929-75e9e4, J2 (i): py_compile and a plain
import of the seven extracted modules (./impl), NO function called. Permitted
by VB-4 as a dry import. Records sha256, compile status, import status and the
public callables each module defines."""
import hashlib, importlib, json, os, py_compile, sys
HERE = os.path.dirname(os.path.abspath(__file__))
IMPL = os.path.join(HERE, "impl")
sys.path.insert(0, IMPL)
mods = ["binstd_core", "certificate", "estimator", "stage1_gate", "families", "calibration_rows", "stage0"]
res = {"python": sys.version.split()[0]}
for m in mods:
    fn = os.path.join(IMPL, m + ".py")
    r = {"sha256": hashlib.sha256(open(fn, "rb").read()).hexdigest()}
    try:
        py_compile.compile(fn, cfile=os.path.join(HERE, "pyc_" + m + ".pyc"), doraise=True)
        r["py_compile"] = "ok"
    except Exception as e:
        r["py_compile"] = "FAIL %r" % e
    try:
        mod = importlib.import_module(m)
        r["import"] = "ok"
        r["callables"] = sorted(k for k, v in vars(mod).items() if callable(v) and not k.startswith("_") and getattr(v, "__module__", None) == m)
    except Exception as e:
        r["import"] = "FAIL %r" % e
    res[m] = r
print(json.dumps(res, indent=1))

