"""Review computation, TASK-20260929-75e9e4, J2: can the repaired shuffle's gate
checks FAIL? (R-1: "pin it with a criterion it can fail".)

Synthetic Z/8012 only (not a declared cell). The PC-6a and PC-6b criteria are
evaluated exactly as CODE-GATE check_gate states them (shuffle median <= q99;
L1 and kept >= 3 W and not L3), using CODE-EST's gain, null_distribution,
null_summary, seed_rows and clause functions, but with the committed shuffle
REPLACED by three deliberately broken shuffles written here:
  BROKEN-ID      the identity map (labels unchanged);
  BROKEN-RELABEL a permutation of the alphabet applied to every label (the
                 version-1 defect DEV-J2-1: G is invariant under it);
  BROKEN-UNIFORM fresh uniform labels (destroys the marginal).
A correct gate must FAIL PC-6a under BROKEN-ID and BROKEN-RELABEL, and FAIL
PC-6b under BROKEN-UNIFORM. The committed shuffle is run alongside as control.
"""
import json
import os
import random
import sys
from array import array

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "impl"))
import estimator as est  # noqa: E402


class SynthZ:
    def __init__(self, cid, N):
        self.id, self.N = cid, N

    def sample(self, rng):
        return rng.randrange(1, self.N)

    def add(self, i, j):
        s = (i + j) % self.N
        return None if s == 0 else s

    def key(self, i):
        return i

    def unpack(self, k):
        return k


def shuf_committed(lab, U, seed, M):
    return est.shuffled(lab, U, seed)


def shuf_id(lab, U, seed, M):
    return array("H", lab[0:U])


def shuf_relabel(lab, U, seed, M):
    perm = list(range(M))
    random.Random(seed).shuffle(perm)
    return array("H", [perm[v] for v in lab[0:U]])


def shuf_uniform(lab, U, seed, M):
    rng = random.Random(seed)
    return array("H", [rng.randrange(M) for _ in range(U)])


SHUFFLES = {"COMMITTED": shuf_committed, "BROKEN-ID": shuf_id,
            "BROKEN-RELABEL": shuf_relabel, "BROKEN-UNIFORM": shuf_uniform}


def read_arm_with(shuf, stream, S, U, lab, M, cid, arm, s):
    direct = est.gain(stream, S, lab, M)
    sh = [est.gain(stream, S, shuf(lab, U, est.seed_of("sh", cid, arm, M, s, r), M), M)["G"]
          for r in range(est.R_SH)]
    return {"direct": direct, "shuffle": sh}


def pc6a(shuf, N=8012, M=4, tag="SYN-FAIL"):
    cell = SynthZ(tag, N)
    S = est.S_of(M)
    draws, meds = [], []
    for s in range(10):
        st = est.PairStream(cell, s, S)
        U = st.support(S)
        lab = est.cache_labels(cell, st, U, lambda i: i % M)
        rd = read_arm_with(shuf, st, S, U, lab, M, cell.id, "exact", s)
        meds.append(est.median(rd["shuffle"]))
        draws.extend(est.null_distribution(st, S, U, M, cell.id, s))
    ns = est.null_summary(draws)
    return {"q99": round(ns["q99"], 4), "max_shuffle_median": round(max(meds), 4),
            "PC6a_pass": all(m <= ns["q99"] for m in meds)}


def pc6b(shuf, N=8012, M=16, tag="SYN-FAIL"):
    cell = SynthZ(tag, N)
    S = est.S_of(M)
    draws, readings = [], []
    for s in range(10):
        st = est.PairStream(cell, s, S)
        U = st.support(S)
        lab = est.planted_marginal_labels(U, M, est.seed_of("planted", cell.id, M, s))
        readings.append(read_arm_with(shuf, st, S, U, lab, M, cell.id, "planted", s))
        draws.extend(est.null_distribution(st, S, U, M, cell.id, s))
    ns = est.null_summary(draws)
    rows = est.seed_rows(readings, ns)
    kept = est.median([est.median(r["shuffle"]) for r in readings]) - ns["q50"]
    L1, L3 = est.clause_L1(rows, ns), est.clause_L3(rows, ns)
    return {"W": round(ns["W"], 4), "kept_over_W": round(kept / ns["W"], 3), "L1": L1, "L3": L3,
            "PC6b_pass": bool(L1 and kept >= 3 * ns["W"] and not L3)}


def main():
    out = {}
    for name, f in SHUFFLES.items():
        out[name] = {"PC-6a (exact mod 4, M=4, S=2048)": pc6a(f),
                     "PC-6b (planted, M=16, S=32768)": pc6b(f)}
    print(json.dumps(out, indent=1))


if __name__ == "__main__":
    main()

